<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_customizer( $wp_customize ) { $wp_customize->add_panel( 'sd_settings', array( 'title' => __( 'Social Discovery', 'social-discovery' ), 'priority' => 30, 'description' => __( 'Configure the Social Discovery theme foundation.', 'social-discovery' ) ) ); }
add_action( 'customize_register', 'sd_customizer' );
function sd_sanitize_select( $value, $setting ) { $control = $setting->manager->get_control( $setting->id ); return $control && array_key_exists( $value, $control->choices ) ? $value : $setting->default; }
function sd_sanitize_url( $value ) { return esc_url_raw( $value ); }
function sd_sanitize_positive_int( $value ) { return min( 2000, max( 0, absint( $value ) ) ); }
function sd_customizer_css() { printf( '<style>:root{--sd-primary:%1$s;--sd-primary-hover:%2$s;--sd-secondary:%3$s;--sd-accent:%4$s;--sd-container:%5$spx;--sd-reading-width:%6$spx;--sd-header-height:%7$spx;--sd-header-background:%8$s;--sd-header-text:%9$s;--sd-header-border:%10$s;--sd-header-shadow:%11$s;--sd-footer-background:%12$s;--sd-footer-text:%13$s;--sd-footer-heading:%14$s;--sd-directory-columns:%15$d;}</style>', esc_attr( sd_get_option( 'sd_primary_color' ) ), esc_attr( sd_get_option( 'sd_primary_hover' ) ), esc_attr( sd_get_option( 'sd_secondary_color' ) ), esc_attr( sd_get_option( 'sd_accent_color' ) ), absint( sd_get_option( 'sd_header_container_width' ) ), absint( sd_get_option( 'sd_reading_width' ) ), absint( sd_get_option( 'sd_header_height' ) ), esc_attr( sd_get_option( 'sd_header_background' ) ), esc_attr( sd_get_option( 'sd_header_text_color' ) ), sd_get_option( 'sd_header_border' ) ? '1px solid' : '0', sd_get_option( 'sd_header_shadow' ) ? '0 8px 24px rgba(15,23,42,.08)' : 'none', esc_attr( sd_get_option( 'sd_footer_background' ) ), esc_attr( sd_get_option( 'sd_footer_text_color' ) ), esc_attr( sd_get_option( 'sd_footer_heading_color' ) ), absint( sd_get_option( 'sd_social_directory_columns', 3 ) ) ); }
add_action( 'wp_head', 'sd_customizer_css' );
